UPDATE report r
SET r.status = #{report.status}
WHERE r.id = #{reportId}
    AND #{report.status} IN ('IN_REVIEW', 'REJECTED', 'RESOLVED')
    AND r.status IN ('PENDING', 'IN_REVIEW')

UPDATE report
SET status = 'CANCELLED'
WHERE id = #{reportId}
    AND reporter_id = #{reporteId}
    AND status <> 'CANCELLED'
